# Sourced by the rules_atlas wrappers. Pure bash, no host tools.
#
# envsubst TEMPLATE
#   Prints TEMPLATE with every `${NAME}` and `$NAME` replaced by the value of
#   the variable NAME (empty when unset), like gettext's `envsubst` with no
#   SHELL-FORMAT argument. Values are copied verbatim: nothing is eval'd, so
#   autogenerated passwords with shell metacharacters survive. A `$` not
#   followed by a name is kept as is. The function's locals are prefixed
#   `__es_`; a variable with that prefix would read as the local.
envsubst() {
  local __es_rest="$1" __es_out="" __es_name
  local __es_var='^([^$]*)\$(\{([A-Za-z_][A-Za-z0-9_]*)\}|([A-Za-z_][A-Za-z0-9_]*))'
  local __es_lit='^([^$]*\$?)'
  while [[ -n "$__es_rest" ]]; do
    if [[ "$__es_rest" =~ $__es_var ]]; then
      __es_name="${BASH_REMATCH[3]:-${BASH_REMATCH[4]}}"
      __es_out+="${BASH_REMATCH[1]}${!__es_name-}"
    else
      [[ "$__es_rest" =~ $__es_lit ]]
      __es_out+="${BASH_REMATCH[0]}"
    fi
    __es_rest="${__es_rest:${#BASH_REMATCH[0]}}"
  done
  printf '%s' "$__es_out"
}
